fn assert_metrics_exact_eq(
    actual: Option<&IntrinsicStrictCompletedMetricsExact>,
    expected: &Value,
    label: &str,
) {
    if expected.is_null() {
        assert!(
            actual.is_none(),
            "{label}.exact: expected None, got {actual:?}"
        );
        return;
    }
    let actual = actual.unwrap_or_else(|| panic!("{label}.exact: expected Some, got None"));
    assert_f64_bits_eq(
        actual.envelope_maximum_side_grid,
        get_str(expected, "envelopeMaximumSideGrid"),
        &format!("{label}.exact.envelopeMaximumSideGrid"),
    );
    assert_eq!(
        actual.envelope_area_grid2,
        get_str(expected, "envelopeAreaGrid2"),
        "{label}.exact.envelopeAreaGrid2"
    );
    assert_f64_bits_eq(
        actual.envelope_span_grid,
        get_str(expected, "envelopeSpanGrid"),
        &format!("{label}.exact.envelopeSpanGrid"),
    );
    assert_eq!(
        actual.total_enclosed_cavity_doubled_area_grid2,
        get_str(expected, "totalEnclosedCavityDoubledAreaGrid2"),
        "{label}.exact.totalEnclosedCavityDoubledAreaGrid2"
    );
    assert_eq!(
        actual.largest_occupied_hull_gap_doubled_area_grid2,
        get_str(expected, "largestOccupiedHullGapDoubledAreaGrid2"),
        "{label}.exact.largestOccupiedHullGapDoubledAreaGrid2"
    );
    assert_eq!(
        actual.occupied_hull_doubled_area_grid2,
        get_str(expected, "occupiedHullDoubledAreaGrid2"),
        "{label}.exact.occupiedHullDoubledAreaGrid2"
    );
    assert_eq!(
        actual.occupied_hull_waste_doubled_area_grid2,
        get_str(expected, "occupiedHullWasteDoubledAreaGrid2"),
        "{label}.exact.occupiedHullWasteDoubledAreaGrid2"
    );
    assert_f64_bits_eq(
        actual.largest_positive_contact_component_size,
        get_str(expected, "largestPositiveContactComponentSize"),
        &format!("{label}.exact.largestPositiveContactComponentSize"),
    );
    assert_f64_bits_eq(
        actual.placed_piece_count,
        get_str(expected, "placedPieceCount"),
        &format!("{label}.exact.placedPieceCount"),
    );
    assert_eq!(
        actual.occupied_outside_largest_contact_component_doubled_area_grid2,
        get_str(
            expected,
            "occupiedOutsideLargestContactComponentDoubledAreaGrid2"
        ),
        "{label}.exact.occupiedOutsideLargestContactComponentDoubledAreaGrid2"
    );
}

