fn assert_certificate_eq(
    actual: Option<&irregular_nesting_native::search::strict_decoder::IntrinsicStrictCertificate>,
    expected: &Value,
    label: &str,
) {
    if expected.is_null() {
        assert!(actual.is_none(), "{label}: expected None, got {actual:?}");
        return;
    }
    let actual = actual.unwrap_or_else(|| panic!("{label}: expected Some, got None"));
    assert_eq!(
        actual.passes,
        expected["passes"].as_bool().expect("passes present"),
        "{label}.passes"
    );
    let expected_floors: Vec<IntrinsicStrictCohesionFloor> = expected["violatedFloors"]
        .as_array()
        .expect("violatedFloors present")
        .iter()
        .map(|v| serde_json::from_value(v.clone()).expect("valid cohesion floor"))
        .collect();
    assert_eq!(
        actual.violated_floors, expected_floors,
        "{label}.violatedFloors"
    );
    assert_f64_bits_eq(
        actual.relative_deficit_sum,
        get_str(expected, "relativeDeficitSum"),
        &format!("{label}.relativeDeficitSum"),
    );
    match &expected["exactRelativeDeficitNumerator"] {
        Value::Null => assert!(
            actual.exact_relative_deficit_numerator.is_none(),
            "{label}.exactRelativeDeficitNumerator: expected None"
        ),
        Value::String(s) => assert_eq!(
            actual.exact_relative_deficit_numerator.as_deref(),
            Some(s.as_str()),
            "{label}.exactRelativeDeficitNumerator"
        ),
        other => panic!("unexpected shape {other:?}"),
    }
    match &expected["exactRelativeDeficitDenominator"] {
        Value::Null => assert!(
            actual.exact_relative_deficit_denominator.is_none(),
            "{label}.exactRelativeDeficitDenominator: expected None"
        ),
        Value::String(s) => assert_eq!(
            actual.exact_relative_deficit_denominator.as_deref(),
            Some(s.as_str()),
            "{label}.exactRelativeDeficitDenominator"
        ),
        other => panic!("unexpected shape {other:?}"),
    }
}

fn assert_placements_eq(actual: &[IrregularPlacement], expected: &Value, label: &str) {
    let expected = expected.as_array().expect("placements array present");
    assert_eq!(
        actual.len(),
        expected.len(),
        "{label}: placement count mismatch"
    );
    for (index, (a, e)) in actual.iter().zip(expected.iter()).enumerate() {
        let entry_label = format!("{label}[{index}]");
        assert_eq!(
            a.source_piece_id.as_str(),
            get_str(e, "pieceId"),
            "{entry_label}.pieceId"
        );
        assert_f64_bits_eq(
            a.transform.translate_x,
            get_str(e, "translateX"),
            &format!("{entry_label}.translateX"),
        );
        assert_f64_bits_eq(
            a.transform.translate_y,
            get_str(e, "translateY"),
            &format!("{entry_label}.translateY"),
        );
        assert_f64_bits_eq(
            a.transform.rotation_deg,
            get_str(e, "rotationDeg"),
            &format!("{entry_label}.rotationDeg"),
        );
        assert_eq!(
            a.transform.mirrored,
            e["mirrored"].as_bool().expect("mirrored present"),
            "{entry_label}.mirrored"
        );
    }
}

fn assert_step_trace_eq(
    actual: &[irregular_nesting_native::search::strict_decoder::IntrinsicStrictStepTrace],
    expected: &Value,
    label: &str,
) {
    let expected = expected.as_array().expect("stepTrace array present");
    assert_eq!(
        actual.len(),
        expected.len(),
        "{label}: stepTrace length mismatch"
    );
    for (index, (a, e)) in actual.iter().zip(expected.iter()).enumerate() {
        let entry_label = format!("{label}[{index}]");
        assert_eq!(
            a.piece_id.as_str(),
            get_str(e, "pieceId"),
            "{entry_label}.pieceId"
        );
        assert_f64_bits_eq(
            a.candidate_count,
            get_str(e, "candidateCount"),
            &format!("{entry_label}.candidateCount"),
        );
        assert_f64_bits_eq(
            a.transform_family_count,
            get_str(e, "transformFamilyCount"),
            &format!("{entry_label}.transformFamilyCount"),
        );
        match &e["selectedTransformFamily"] {
            Value::Null => assert!(
                a.selected_transform_family.is_none(),
                "{entry_label}.selectedTransformFamily: expected None"
            ),
            Value::String(s) => assert_eq!(
                a.selected_transform_family.as_deref(),
                Some(s.as_str()),
                "{entry_label}.selectedTransformFamily"
            ),
            other => panic!("unexpected shape {other:?}"),
        }
        match (&a.selected_score, &e["selectedScore"]) {
            (None, Value::Null) => {}
            (Some(score), score_json) if !score_json.is_null() => {
                assert_f64_bits_eq(
                    score.maximum_side_mm,
                    get_str(score_json, "maximumSideMm"),
                    &format!("{entry_label}.selectedScore.maximumSideMm"),
                );
                assert_f64_bits_eq(
                    score.envelope_area_mm2,
                    get_str(score_json, "envelopeAreaMm2"),
                    &format!("{entry_label}.selectedScore.envelopeAreaMm2"),
                );
                assert_f64_bits_eq(
                    score.envelope_span_mm,
                    get_str(score_json, "envelopeSpanMm"),
                    &format!("{entry_label}.selectedScore.envelopeSpanMm"),
                );
                assert_f64_bits_eq(
                    score.shared_boundary_length_mm,
                    get_str(score_json, "sharedBoundaryLengthMm"),
                    &format!("{entry_label}.selectedScore.sharedBoundaryLengthMm"),
                );
                assert_eq!(
                    score.canonical_combined_geometry_key,
                    get_str(score_json, "canonicalCombinedGeometryKey"),
                    "{entry_label}.selectedScore.canonicalCombinedGeometryKey"
                );
                match (&score.exact, &score_json["exact"]) {
                    (None, Value::Null) => {}
                    (Some(exact), exact_json) if !exact_json.is_null() => {
                        assert_f64_bits_eq(
                            exact.maximum_side_grid,
                            get_str(exact_json, "maximumSideGrid"),
                            &format!("{entry_label}.selectedScore.exact.maximumSideGrid"),
                        );
                        assert_eq!(
                            exact.envelope_area_grid2,
                            get_str(exact_json, "envelopeAreaGrid2"),
                            "{entry_label}.selectedScore.exact.envelopeAreaGrid2"
                        );
                        assert_f64_bits_eq(
                            exact.envelope_span_grid,
                            get_str(exact_json, "envelopeSpanGrid"),
                            &format!("{entry_label}.selectedScore.exact.envelopeSpanGrid"),
                        );
                    }
                    other => {
                        panic!("{entry_label}.selectedScore.exact presence mismatch: {other:?}")
                    }
                }
            }
            other => panic!("{entry_label}.selectedScore presence mismatch: {other:?}"),
        }
    }
}

fn decode_status(raw: &str) -> IntrinsicStrictDecodeStatus {
    match raw {
        "completed" => IntrinsicStrictDecodeStatus::Completed,
        "incomplete" => IntrinsicStrictDecodeStatus::Incomplete,
        "infeasible-final-sheet" => IntrinsicStrictDecodeStatus::InfeasibleFinalSheet,
        other => panic!("unrecognized status: {other}"),
    }
}

fn decode_terminal_rotation(raw: f64) -> TerminalRotationDeg {
    if raw == 0.0 {
        TerminalRotationDeg::Zero
    } else if raw == 90.0 {
        TerminalRotationDeg::Ninety
    } else {
        panic!("unrecognized terminal rotation: {raw}")
    }
}

