#[allow(clippy::too_many_arguments)]
fn run_construct<'a>(
    pieces: &'a [Arc<IrregularPreparedPiece>],
    candidate_mode: IntrinsicStrictCandidateMode,
    maximum_runtime_ms: f64,
    maximum_candidate_evaluation_count: Option<f64>,
    maximum_completed_piece_boundaries: Option<f64>,
    capture_phase_timings: bool,
    checkpoint: Option<
        irregular_nesting_native::search::strict_decoder::IntrinsicStrictDirectCheckpoint,
    >,
    timing_now: &'a TimingNowFn,
    settings: &IrregularNestingSettings,
    cache: &mut GeometryCacheStore,
) -> Result<
    irregular_nesting_native::search::strict_decoder::IntrinsicStrictConstructResult,
    IntrinsicStrictDecoderFailure,
> {
    let input = ConstructIntrinsicStrictStateInput {
        all_prepared_pieces: pieces,
        remaining_prepared_pieces: pieces,
        frozen_placed: &[],
        candidate_mode,
        maximum_runtime_ms: Some(maximum_runtime_ms),
        maximum_candidate_evaluation_count,
        capture_candidate_evaluation_count: true,
        capture_phase_timings,
        timing_now: Some(timing_now),
        producer_role: None,
        checkpoint,
        maximum_completed_piece_boundaries,
        control: None,
    };
    construct_intrinsic_strict_state(input, settings, cache)
}

#[test]
fn decode_cases_match_ts() {
    let vectors = load_vectors();
    let nesting_settings = settings(&vectors);
    let cases = vectors["decodeCases"]
        .as_array()
        .expect("decodeCases present");
    assert!(!cases.is_empty(), "expected at least one decode case");
    for case in cases {
        let label = get_str(case, "caseLabel");
        let pieces = decode_prepared_pieces(&case["pieces"]);
        let candidate_mode = candidate_mode_from_label(get_str(case, "candidateMode"));
        let maximum_runtime_ms = get_f64(case, "maximumRuntimeMs");
        let sheet = SheetSpec {
            width: get_f64(case, "finalSheetWidth"),
            height: get_f64(case, "finalSheetHeight"),
            label: "vector-sheet".to_string(),
        };
        let clock = make_clock();
        let mut cache = GeometryCacheStore::new();
        let result = run_construct(
            &pieces,
            candidate_mode,
            maximum_runtime_ms,
            None,
            None,
            false,
            None,
            &clock,
            &nesting_settings,
            &mut cache,
        );
        let expected = &case["result"];
        let expected_exit_tag = get_str(expected, "exitTag");
        match result {
            Ok(constructed) => {
                assert_eq!(
                    expected_exit_tag, "Success",
                    "{label}: expected exitTag Success"
                );
                let runtime_ms = constructed.runtime_ms;
                let candidate_evaluation_count = constructed.candidate_evaluation_count;
                let step_trace_owned = constructed.step_trace.clone();
                let finalized = finalize_intrinsic_strict_state(&sheet, constructed, runtime_ms)
                    .unwrap_or_else(|err| panic!("{label}: unexpected finalize failure: {err:?}"));
                assert_eq!(
                    finalized.status,
                    decode_status(get_str(expected, "status")),
                    "{label}: status"
                );
                match (
                    finalized.terminal_rotation_deg,
                    &expected["terminalRotationDeg"],
                ) {
                    (None, Value::Null) => {}
                    (Some(actual), Value::Number(n)) => {
                        let expected_rotation =
                            decode_terminal_rotation(n.as_f64().expect("finite rotation"));
                        assert_eq!(actual, expected_rotation, "{label}: terminalRotationDeg");
                    }
                    other => panic!("{label}: terminalRotationDeg presence mismatch: {other:?}"),
                }
                match (
                    &finalized.canonical_geometry_hash,
                    &expected["canonicalGeometryHash"],
                ) {
                    (None, Value::Null) => {}
                    (Some(actual), Value::String(s)) => {
                        assert_eq!(actual, s, "{label}: canonicalGeometryHash")
                    }
                    other => panic!("{label}: canonicalGeometryHash presence mismatch: {other:?}"),
                }
                assert_placements_eq(
                    &finalized.placements,
                    &expected["placements"],
                    &format!("{label}.placements"),
                );
                let expected_unplaced: Vec<&str> = expected["unplacedPieceIds"]
                    .as_array()
                    .expect("unplacedPieceIds present")
                    .iter()
                    .map(|v| v.as_str().expect("unplaced id string"))
                    .collect();
                let actual_unplaced: Vec<&str> = finalized
                    .unplaced_piece_ids
                    .iter()
                    .map(|id| id.as_str())
                    .collect();
                assert_eq!(
                    actual_unplaced, expected_unplaced,
                    "{label}: unplacedPieceIds"
                );
                assert_metrics_eq(
                    finalized.metrics.as_ref(),
                    &expected["metrics"],
                    &format!("{label}.metrics"),
                );
                assert_certificate_eq(
                    finalized.certificate.as_ref(),
                    &expected["certificate"],
                    &format!("{label}.certificate"),
                );
                assert_step_trace_eq(
                    &finalized.step_trace,
                    &expected["stepTrace"],
                    &format!("{label}.stepTrace"),
                );
                let _ = step_trace_owned;
                assert_opt_f64_bits_eq(
                    candidate_evaluation_count,
                    &expected["candidateEvaluationCount"],
                    &format!("{label}.candidateEvaluationCount"),
                );
                assert_f64_bits_eq(
                    finalized.runtime_ms,
                    get_str(expected, "runtimeMs"),
                    &format!("{label}.runtimeMs"),
                );
            }
            Err(failure) => {
                assert_eq!(
                    expected_exit_tag, "Failure",
                    "{label}: expected exitTag Failure, got {failure:?}"
                );
                assert_failure_matches(&failure, &expected["failure"], label);
            }
        }
    }
}

fn assert_failure_matches(failure: &IntrinsicStrictDecoderFailure, expected: &Value, label: &str) {
    let expected_tag = get_str(expected, "tag");
    match failure {
        IntrinsicStrictDecoderFailure::Decoder(err) => {
            assert_eq!(
                expected_tag, "IntrinsicStrictDecoderError",
                "{label}: failure tag"
            );
            if let Some(message) = expected["message"].as_str() {
                assert_eq!(err.message, message, "{label}: failure message");
            }
        }
        IntrinsicStrictDecoderFailure::Geometry(err) => {
            assert_eq!(
                expected_tag, "IrregularGeometryInputError",
                "{label}: failure tag"
            );
            let _ = err;
        }
        IntrinsicStrictDecoderFailure::Abort(err) => {
            assert_eq!(
                expected_tag, "IrregularNfpIfpControlAbortError",
                "{label}: failure tag"
            );
            let expected_reason = expected["reason"].as_str();
            let actual_reason = match err.reason {
                NfpIfpAbortReason::Deadline => "deadline",
                NfpIfpAbortReason::Cancelled => "cancelled",
            };
            if let Some(expected_reason) = expected_reason {
                assert_eq!(actual_reason, expected_reason, "{label}: failure reason");
            }
            if let Some(message) = expected["message"].as_str() {
                assert_eq!(err.message, message, "{label}: failure message");
            }
        }
    }
}

