// ===========================================================================
// Section E: deadline-abort cases.
// ===========================================================================
#[test]
fn deadline_cases_match_ts() {
    let vectors = load_vectors();
    let nesting_settings = settings(&vectors);
    let cases = vectors["deadlineCases"]
        .as_array()
        .expect("deadlineCases present");
    assert!(!cases.is_empty(), "expected at least one deadline case");
    for case in cases {
        let label = get_str(case, "caseLabel");
        let pieces = decode_prepared_pieces(&case["pieces"]);
        let candidate_mode = candidate_mode_from_label(get_str(case, "candidateMode"));
        let maximum_runtime_ms = get_f64(case, "maximumRuntimeMs");
        let previous_active_runtime_ms = get_f64(case, "previousActiveRuntimeMs");
        let expect_failure = case["expectFailure"]
            .as_bool()
            .expect("expectFailure present");

        let result = if previous_active_runtime_ms != 0.0 {
            // The resumed-checkpoint case: replay stage 1 (with the same
            // shared `maximumRuntimeMs`, since it is hashed into the
            // checkpoint's own requestFingerprint) to obtain a real Rust
            // checkpoint whose `activeRuntimeMs` must match the recorded
            // `previousActiveRuntimeMs` exactly, then resume it.
            let mut cache1 = GeometryCacheStore::new();
            let clock1 = make_clock();
            let stage1 = run_construct(
                &pieces,
                candidate_mode,
                maximum_runtime_ms,
                None,
                Some(1.0),
                false,
                None,
                &clock1,
                &nesting_settings,
                &mut cache1,
            )
            .unwrap_or_else(|err| panic!("{label}: unexpected stage-1 failure: {err:?}"));
            let checkpoint = stage1
                .checkpoint
                .unwrap_or_else(|| panic!("{label}: expected a stage-1 checkpoint"));
            assert_f64_bits_eq(
                checkpoint.active_runtime_ms,
                get_str(case, "previousActiveRuntimeMs"),
                &format!("{label}: stage-1 checkpoint.activeRuntimeMs"),
            );
            let mut cache2 = GeometryCacheStore::new();
            let clock2 = make_clock();
            run_construct(
                &pieces,
                candidate_mode,
                maximum_runtime_ms,
                None,
                None,
                false,
                Some(checkpoint),
                &clock2,
                &nesting_settings,
                &mut cache2,
            )
        } else {
            let clock = make_clock();
            let mut cache = GeometryCacheStore::new();
            run_construct(
                &pieces,
                candidate_mode,
                maximum_runtime_ms,
                None,
                None,
                false,
                None,
                &clock,
                &nesting_settings,
                &mut cache,
            )
        };

        match result {
            Ok(_) => assert!(
                !expect_failure,
                "{label}: expected a deadline failure, got Success"
            ),
            Err(failure) => {
                assert!(
                    expect_failure,
                    "{label}: expected Success, got failure {failure:?}"
                );
                match failure {
                    IntrinsicStrictDecoderFailure::Abort(err) => {
                        let actual_reason = match err.reason {
                            NfpIfpAbortReason::Deadline => "deadline",
                            NfpIfpAbortReason::Cancelled => "cancelled",
                        };
                        assert_eq!(actual_reason, get_str(case, "reason"), "{label}: reason");
                        assert_eq!(err.message, get_str(case, "message"), "{label}: message");
                    }
                    other => panic!("{label}: expected an Abort failure, got {other:?}"),
                }
            }
        }
    }
}

// ===========================================================================
// Section F: Pareto/ranking cases.
// ===========================================================================
fn decode_metrics_exact(value: &Value) -> Option<IntrinsicStrictCompletedMetricsExact> {
    if value.is_null() {
        return None;
    }
    Some(IntrinsicStrictCompletedMetricsExact {
        envelope_maximum_side_grid: get_f64(value, "envelopeMaximumSideGrid"),
        envelope_area_grid2: get_str(value, "envelopeAreaGrid2").to_string(),
        envelope_span_grid: get_f64(value, "envelopeSpanGrid"),
        total_enclosed_cavity_doubled_area_grid2: get_str(
            value,
            "totalEnclosedCavityDoubledAreaGrid2",
        )
        .to_string(),
        largest_occupied_hull_gap_doubled_area_grid2: get_str(
            value,
            "largestOccupiedHullGapDoubledAreaGrid2",
        )
        .to_string(),
        occupied_hull_doubled_area_grid2: get_str(value, "occupiedHullDoubledAreaGrid2")
            .to_string(),
        occupied_hull_waste_doubled_area_grid2: get_str(value, "occupiedHullWasteDoubledAreaGrid2")
            .to_string(),
        largest_positive_contact_component_size: get_f64(
            value,
            "largestPositiveContactComponentSize",
        ),
        placed_piece_count: get_f64(value, "placedPieceCount"),
        occupied_outside_largest_contact_component_doubled_area_grid2: get_str(
            value,
            "occupiedOutsideLargestContactComponentDoubledAreaGrid2",
        )
        .to_string(),
    })
}

fn decode_metrics(value: &Value) -> IntrinsicStrictCompletedMetrics {
    IntrinsicStrictCompletedMetrics {
        envelope_maximum_side_mm: get_f64(value, "envelopeMaximumSideMm"),
        envelope_area_mm2: get_f64(value, "envelopeAreaMm2"),
        envelope_span_mm: get_f64(value, "envelopeSpanMm"),
        enclosed_cavity_count: get_f64(value, "enclosedCavityCount"),
        total_enclosed_cavity_area_mm2: get_f64(value, "totalEnclosedCavityAreaMm2"),
        largest_occupied_hull_gap_ratio: get_f64(value, "largestOccupiedHullGapRatio"),
        isolated_piece_count: get_f64(value, "isolatedPieceCount"),
        positive_contact_component_count: get_f64(value, "positiveContactComponentCount"),
        largest_positive_contact_component_size: get_f64(
            value,
            "largestPositiveContactComponentSize",
        ),
        largest_positive_contact_component_ratio: get_f64(
            value,
            "largestPositiveContactComponentRatio",
        ),
        occupied_area_outside_largest_contact_component_mm2: get_f64(
            value,
            "occupiedAreaOutsideLargestContactComponentMm2",
        ),
        occupied_hull_waste_ratio: get_f64(value, "occupiedHullWasteRatio"),
        total_structural_contacts: get_f64(value, "totalStructuralContacts"),
        dominant_structural_contacts: get_f64(value, "dominantStructuralContacts"),
        contact_units: get_f64(value, "contactUnits"),
        shared_boundary_length_mm: get_f64(value, "sharedBoundaryLengthMm"),
        canonical_geometry_hash: get_str(value, "canonicalGeometryHash").to_string(),
        runtime_ms: get_f64(value, "runtimeMs"),
        exact: decode_metrics_exact(&value["exact"]),
    }
}

#[test]
fn pareto_cases_match_ts() {
    let vectors = load_vectors();
    let cases = vectors["paretoCases"]
        .as_array()
        .expect("paretoCases present");
    assert!(!cases.is_empty(), "expected at least one pareto case");
    for case in cases {
        let label = get_str(case, "caseLabel");
        let pool: Vec<IntrinsicStrictCompletedMetrics> = case["pool"]
            .as_array()
            .expect("pool present")
            .iter()
            .map(decode_metrics)
            .collect();

        let ranked = rank_intrinsic_strict_completed_layouts(&pool);
        let expected_ranked: Vec<&str> = case["rankedHashes"]
            .as_array()
            .expect("rankedHashes present")
            .iter()
            .map(|v| v.as_str().expect("hash string"))
            .collect();
        let actual_ranked: Vec<&str> = ranked
            .iter()
            .map(|m| m.canonical_geometry_hash.as_str())
            .collect();
        assert_eq!(actual_ranked, expected_ranked, "{label}: rankedHashes");

        let front = select_intrinsic_strict_completed_pareto_front(&pool);
        let expected_front: Vec<&str> = case["frontHashes"]
            .as_array()
            .expect("frontHashes present")
            .iter()
            .map(|v| v.as_str().expect("hash string"))
            .collect();
        let actual_front: Vec<&str> = front
            .iter()
            .map(|m| m.canonical_geometry_hash.as_str())
            .collect();
        assert_eq!(actual_front, expected_front, "{label}: frontHashes");

        let expected_dominance = case["dominanceMatrix"]
            .as_array()
            .expect("dominanceMatrix present");
        let expected_dominates = case["dominatesMatrix"]
            .as_array()
            .expect("dominatesMatrix present");
        assert_eq!(
            pool.len(),
            expected_dominance.len(),
            "{label}: dominanceMatrix row count"
        );
        for (i, first) in pool.iter().enumerate() {
            let expected_row = expected_dominance[i]
                .as_array()
                .expect("dominance row present");
            let expected_dominates_row = expected_dominates[i]
                .as_array()
                .expect("dominates row present");
            assert_eq!(
                pool.len(),
                expected_row.len(),
                "{label}: dominanceMatrix[{i}] column count"
            );
            for (j, second) in pool.iter().enumerate() {
                let ordering = compare_intrinsic_strict_completed_layout_dominance(first, second);
                let expected_tag = expected_row[j].as_str().expect("dominance cell string");
                let expected_ordering = match expected_tag {
                    "lt" => Ordering::Less,
                    "gt" => Ordering::Greater,
                    "eq" => Ordering::Equal,
                    other => panic!("unrecognized dominance tag: {other}"),
                };
                assert_eq!(
                    ordering, expected_ordering,
                    "{label}: dominanceMatrix[{i}][{j}]"
                );

                let dominates = intrinsic_strict_completed_layout_dominates(first, second);
                let expected_dominates_cell = expected_dominates_row[j]
                    .as_bool()
                    .expect("dominates cell boolean");
                assert_eq!(
                    dominates, expected_dominates_cell,
                    "{label}: dominatesMatrix[{i}][{j}]"
                );
            }
        }
    }
}

